// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">Angular Signal <code>effect</code> is handy, but it has a few pitfalls. In particular, many developers hit the case where it does not react when you set the same value again.<br>\nFor example, consider code like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"3\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">      // Runs when the page value changes</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'page changed:'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"17\" class=\"code-line\">In this code, the <code>effect</code> runs whenever <code>page</code> changes. Because it is memoized, setting the same value again does not run the effect.<br>\nIn real apps, though, you sometimes want to run other work even when the value did not change. For example, you may want to reload data when <code>page.set(0)</code> fires. Pull-to-refresh with Ionic's <code>ion-refresher</code> is a typical case.</p>\n<h2 id=\"implementing-a-signal-extension\" data-line=\"21\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#implementing-a-signal-extension\" aria-hidden=\"true\"></a> Implementing a Signal extension</h2>\n<p data-line=\"23\" class=\"code-line\">To handle this, I built an extension that makes effect triggering explicit. You can implement it like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"25\"><span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> const</span><span style=\"color:#B392F0\"> pageSignal</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> ()</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> WritableSignal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt; </span><span style=\"color:#F97583\">&amp;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  trigger</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> WritableSignal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;;</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  refresh</span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> void</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> page</span><span style=\"color:#F97583\">  =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> trigger</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> Object.</span><span style=\"color:#B392F0\">assign</span><span style=\"color:#E1E4E8\">(page, {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    trigger,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    refresh</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      page.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      trigger.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">val</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> val </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"42\" class=\"code-line\">I added a <code>trigger</code> Signal so <code>effect</code> and <code>computed</code> can track changes even when setting <code>page</code> does not change its value. I also added a <code>refresh</code> method to update <code>page</code> and <code>trigger</code> together.</p>\n<h2 id=\"use-cases-and-benefits\" data-line=\"45\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#use-cases-and-benefits\" aria-hidden=\"true\"></a> Use cases and benefits</h2>\n<p data-line=\"47\" class=\"code-line\">The biggest benefit is separating user actions such as \"go to next page\" and \"refresh\" from data-fetch logic. In the traditional approach, page updates, reloads, and the fetch that follows are tightly coupled, which tends to make components complex.</p>\n<p data-line=\"49\" class=\"code-line\">For example, \"reset the page to 0 and reload data\" forces you to think about both state changes and fetching in the same place, which hurts readability.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"51\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  items</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Item</span><span style=\"color:#E1E4E8\">[]&gt;([]);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Initial load</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loadData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  refresh</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> RefresherCustomEvent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Reset the page to 0 and reload the data</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loadData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">()).</span><span style=\"color:#B392F0\">finally</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> event.target.</span><span style=\"color:#B392F0\">complete</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loadMore</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> InfiniteScrollCustomEvent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">page</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> page </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loadData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">()).</span><span style=\"color:#B392F0\">finally</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> event.target.</span><span style=\"color:#B392F0\">complete</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#F97583\"> async</span><span style=\"color:#B392F0\"> loadData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">page</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Item</span><span style=\"color:#E1E4E8\">[]&gt;(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> page));</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.items.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">items</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        if</span><span style=\"color:#E1E4E8\"> (page </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]; </span><span style=\"color:#a0aab5\">// Reset the data when the page is 0 or refresh was triggered</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        } </span><span style=\"color:#F97583\">else</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">items, </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]; </span><span style=\"color:#a0aab5\">// Otherwise append to the existing items</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"88\" class=\"code-line\">With the extension, you can centralize \"when should data load?\" in one place and treat page state changes as simple triggers. Because data refetches automatically from state changes, UI logic and data logic stay separate and the code is easier to maintain.</p>\n<h2 id=\"practical-example%3A-infinite-scroll\" data-line=\"91\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#practical-example%3A-infinite-scroll\" aria-hidden=\"true\"></a> Practical example: infinite scroll</h2>\n<p data-line=\"93\" class=\"code-line\">Here is a concrete infinite scroll example:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"95\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;ion-content&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;ion-refresher slot=\"fixed\" (ionRefresh)=\"refresh($event)\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;ion-refresher-content&gt;&lt;/ion-refresher-content&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/ion-refresher&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;ion-list&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        @for(item of items(); track item.id) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">          &lt;ion-item&gt;{{ item.name }}&lt;/ion-item&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        }</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/ion-list&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;ion-infinite-scroll (ionInfinite)=\"loadMore($event)\"&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;ion-infinite-scroll-content&gt;&lt;/ion-infinite-scroll-content&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/ion-infinite-scroll&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;/ion-content&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> InfiniteScrollComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#FFAB70\"> http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> pageSignal</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  items</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Item</span><span style=\"color:#E1E4E8\">[]&gt;([]);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  completeEvent</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">HTMLIonInfiniteScrollElement</span><span style=\"color:#F97583\"> |</span><span style=\"color:#B392F0\"> HTMLIonRefresherElement</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    effect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">      // Runs initially, when the page value changes, or when refresh is triggered</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      const</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#79B8FF\">page</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">trigger</span><span style=\"color:#E1E4E8\">] </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">page</span><span style=\"color:#E1E4E8\">(), </span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">trigger</span><span style=\"color:#E1E4E8\">()];</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Item</span><span style=\"color:#E1E4E8\">[]&gt;(</span><span style=\"color:#9ECBFF\">'/api/users/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> page))</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        .</span><span style=\"color:#B392F0\">finally</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">completeEvent</span><span style=\"color:#E1E4E8\">()?.</span><span style=\"color:#B392F0\">complete</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#a0aab5\">// Call `complete` when a CustomEvent exists</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      </span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.items.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">items</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        if</span><span style=\"color:#E1E4E8\"> (page </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]; </span><span style=\"color:#a0aab5\">// Reset the data when the page is 0 or refresh was triggered</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        } </span><span style=\"color:#F97583\">else</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">          return</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">items, </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">data]; </span><span style=\"color:#a0aab5\">// Otherwise append to the existing items</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  refresh</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> RefresherCustomEvent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">refresh</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.#completeEvent.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(event.target);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  loadMore</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> InfiniteScrollCustomEvent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.page.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">page</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> page </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.#completeEvent.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(event.target);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"152\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"154\" class=\"code-line\">The core idea is separating state management from flexible control. In the traditional approach, page state and reload logic were tightly coupled. With this extension, <code>page</code> and <code>trigger</code> fully separate page state from data reloads.</p>\n<p data-line=\"156\" class=\"code-line\">Signal extensions make it easier to split UI logic from data logic. The pattern fits refresh and infinite scroll especially well, and I plan to use it actively in future work.</p>\n<p data-line=\"158\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"implementing-a-signal-extension","text":"Implementing a Signal extension","level":2},{"id":"use-cases-and-benefits","text":"Use cases and benefits","level":2},{"id":"practical-example%3A-infinite-scroll","text":"Practical example: infinite scroll","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
